import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { financeService } from '../services/api';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import toast from 'react-hot-toast';
import { Plus } from 'lucide-react';


const CATEGORIES = {
  income: [
    { value: 'milk_sale', label: 'Süt Satışı' },
    { value: 'animal_sale', label: 'Hayvan Satışı' },
    { value: 'offspring_sale', label: 'Yavru Satışı' },
    { value: 'wool_sale', label: 'Yün Satışı' },
    { value: 'manure_sale', label: 'Gübre Satışı' },
    { value: 'other_income', label: 'Diğer Gelir' }
  ],
  expense: [
    { value: 'feed', label: 'Yem' },
    { value: 'veterinary', label: 'Veteriner' },
    { value: 'medication', label: 'İlaç' },
    { value: 'labor', label: 'İşçilik' },
    { value: 'equipment', label: 'Ekipman' },
    { value: 'maintenance', label: 'Bakım' },
    { value: 'transport', label: 'Nakliye' },
    { value: 'insurance', label: 'Sigorta' },
    { value: 'tax', label: 'Vergi' },
    { value: 'utility', label: 'Fatura' },
    { value: 'other_expense', label: 'Diğer Gider' }
  ]
};

export default function FinancePage() {
  const { user } = useAuth();
  const farmId = user?.farm_id;

  const [records, setRecords] = useState([]);
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ record_type: '', category: '', from: '', to: '' });
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    record_type: 'income',
    category: 'milk_sale',
    amount: '',
    record_date: new Date().toISOString().split('T')[0],
    description: '',
    payment_method: 'cash',
    notes: ''
  });

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const period = new Date().toISOString().slice(0, 7);
      const res = await financeService.summary(farmId, period);
      setSummary(res.data);
      const listRes = await financeService.list(farmId, filters);
      setRecords(listRes.data.data);
    } catch {
      toast.error('Finansal veriler yüklenemedi');
    } finally {
      setLoading(false);
    }
  }, [farmId, filters]);

  useEffect(() => {
    load();
  }, [load]);

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!form.amount) {
      toast.error('Tutar gerekli');
      return;
    }
    try {
      await financeService.create(farmId, form);
      toast.success('Finansal kayıt eklendi');
      setShowForm(false);
      setForm({
        record_type: 'income',
        category: 'milk_sale',
        amount: '',
        record_date: new Date().toISOString().split('T')[0],
        description: '',
        payment_method: 'cash',
        notes: ''
      });
      load();
    } catch {
      toast.error('İşlem başarısız');
    }
  };

  const getCategories = () => CATEGORIES[form.record_type] || [];

  const chartData = (summary?.details || []).reduce((acc, d) => {
    const existing = acc.find(item => item.category === d.category);
    if (existing) {
      if (d.record_type === 'income') existing.income += parseFloat(d.total);
      else existing.expense += parseFloat(d.total);
    } else {
      acc.push({
        category: d.category,
        income: d.record_type === 'income' ? parseFloat(d.total) : 0,
        expense: d.record_type === 'expense' ? parseFloat(d.total) : 0
      });
    }
    return acc;
  }, []);

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">💰 Finansal Yönetim</h1>
          <p className="text-sm text-gray-500">Gelir, gider ve karlılık takibi</p>
        </div>
        <button onClick={() => setShowForm(!showForm)} className={`btn-primary flex items-center justify-center gap-2 ${showForm ? 'bg-red-500 hover:bg-red-600' : ''}`}>
          {showForm ? 'İptal' : <><Plus className="w-4 h-4" /> İşlem Ekle</>}
        </button>
      </div>

      {/* Özet kartları */}
      {summary && (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="card text-center border-l-4 border-green-500 group hover:bg-green-50/30 transition-colors">
            <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Gelir</p>
            <p className="text-3xl font-black text-green-700 mt-2">₺{summary.income?.toLocaleString('tr-TR')}</p>
          </div>
          <div className="card text-center border-l-4 border-red-500 group hover:bg-red-50/30 transition-colors">
            <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Gider</p>
            <p className="text-3xl font-black text-red-700 mt-2">₺{summary.expense?.toLocaleString('tr-TR')}</p>
          </div>
          <div className={`card text-center border-l-4 ${summary.profit >= 0 ? 'border-blue-500' : 'border-orange-500'} group hover:bg-gray-50/30 transition-colors`}>
            <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Net Kar</p>
            <p className={`text-3xl font-black mt-2 ${summary.profit >= 0 ? 'text-blue-700' : 'text-orange-700'}`}>
              ₺{summary.profit?.toLocaleString('tr-TR')}
            </p>
          </div>
        </div>
      )}

      {/* Form */}
      {showForm && (
        <div className="card border-green-100 bg-green-50/20 animate-in fade-in slide-in-from-top-4">
          <h2 className="text-lg font-bold mb-4 text-green-900">Yeni Finansal İşlem</h2>
          <form onSubmit={handleAdd} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">İşlem Türü</label>
                <select
                  value={form.record_type}
                  onChange={e => {
                    const cats = CATEGORIES[e.target.value] || [];
                    setForm({ ...form, record_type: e.target.value, category: cats[0]?.value || '' });
                  }}
                  className="input-field"
                >
                  <option value="income">Gelir (+)</option>
                  <option value="expense">Gider (-)</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Kategori</label>
                <select
                  value={form.category}
                  onChange={e => setForm({ ...form, category: e.target.value })}
                  className="input-field"
                >
                  {getCategories().map(cat => (
                    <option key={cat.value} value={cat.value}>{cat.label}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Tutar (₺)</label>
                <input
                  type="number"
                  step="0.01"
                  placeholder="0.00"
                  value={form.amount}
                  onChange={e => setForm({ ...form, amount: e.target.value })}
                  className="input-field"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Tarih</label>
                <input
                  type="date"
                  value={form.record_date}
                  onChange={e => setForm({ ...form, record_date: e.target.value })}
                  className="input-field"
                />
              </div>
              <div className="md:col-span-2">
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Ödeme Yöntemi</label>
                <select
                  value={form.payment_method}
                  onChange={e => setForm({ ...form, payment_method: e.target.value })}
                  className="input-field"
                >
                  <option value="cash">Nakit</option>
                  <option value="check">Çek / Senet</option>
                  <option value="bank_transfer">Banka Transferi / Havale</option>
                  <option value="credit_card">Kredi Kartı</option>
                </select>
              </div>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Açıklama</label>
              <textarea
                placeholder="İşlem detayı hakkında kısa bir açıklama..."
                value={form.description}
                onChange={e => setForm({ ...form, description: e.target.value })}
                className="input-field"
                rows={2}
              />
            </div>
            <div className="flex gap-3">
              <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">Vazgeç</button>
              <button type="submit" className="btn-primary flex-1">İşlemi Kaydet</button>
            </div>
          </form>
        </div>
      )}

      {/* Grafik */}
      {chartData.length > 0 && (
        <div className="card">
          <h3 className="font-bold text-gray-900 mb-6">Kategori Bazlı Dağılım</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                <XAxis 
                  dataKey="category" 
                  tick={{ fontSize: 10, fill: '#94a3b8' }} 
                  axisLine={false}
                  tickLine={false}
                />
                <YAxis 
                  tick={{ fontSize: 10, fill: '#94a3b8' }} 
                  axisLine={false}
                  tickLine={false}
                />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                  formatter={(v) => [`₺${parseFloat(v).toLocaleString('tr-TR')}`, '']} 
                />
                <Legend iconType="circle" />
                <Bar dataKey="income" fill="#22c55e" name="Gelir" radius={[4, 4, 0, 0]} barSize={32} />
                <Bar dataKey="expense" fill="#ef4444" name="Gider" radius={[4, 4, 0, 0]} barSize={32} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* İşlem Listesi */}
      <div className="card p-0 overflow-hidden">
        <div className="p-4 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <h3 className="font-bold text-gray-900 whitespace-nowrap">İşlem Geçmişi</h3>
          <div className="flex gap-2 flex-wrap">
            <select
              value={filters.record_type}
              onChange={e => setFilters({ ...filters, record_type: e.target.value })}
              className="input-field text-xs py-1.5 h-auto w-auto min-w-32 bg-white"
            >
              <option value="">Tüm İşlemler</option>
              <option value="income">Sadece Gelirler</option>
              <option value="expense">Sadece Giderler</option>
            </select>
            <input
              type="date"
              value={filters.from}
              onChange={e => setFilters({ ...filters, from: e.target.value })}
              className="input-field text-xs py-1.5 h-auto w-auto bg-white"
            />
            <button onClick={load} className="btn-secondary text-xs px-4 py-1.5 h-auto">Filtrele</button>
          </div>
        </div>

        <div className="overflow-x-auto">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-8 h-8 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : records.length === 0 ? (
            <div className="text-center py-12 text-gray-400">
              <p className="text-4xl mb-2">💰</p>
              <p className="font-medium text-sm">Aranan kriterlerde işlem bulunamadı</p>
            </div>
          ) : (
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tarih</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tür</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Kategori</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Açıklama</th>
                  <th className="text-right px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tutar</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {records.map(r => (
                  <tr key={r.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-gray-600">{r.record_date}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 rounded-md text-[10px] font-black uppercase tracking-widest ${r.record_type === 'income' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                        {r.record_type === 'income' ? 'Gelir' : 'Gider'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-700">{r.category}</td>
                    <td className="px-6 py-4 text-gray-500 max-w-xs truncate">{r.description || '—'}</td>
                    <td className={`px-6 py-4 text-right font-black whitespace-nowrap ${r.record_type === 'income' ? 'text-green-700' : 'text-red-700'}`}>
                      {r.record_type === 'income' ? '+' : '-'} ₺{r.amount?.toLocaleString('tr-TR')}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}